INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0298-a04-007-4', 'p0298', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '術怒，與韓暹、楊奉等連勢，遣大將張勳攻布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0298-a04-046-5', 'p0298', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '太傅馬日磾杖節安集關東，在壽春以禮辟策，表拜懷義校尉，術大將喬蕤、張勳皆傾心敬焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0298-a04-046-6', 'p0298', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '後術死，長史楊弘、大將張勳等將其衆欲就策，廬江太守劉勳要擊，悉虜之，收其珍寶以歸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0299-a03-075-0', 'p0299', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '主簿閻象進曰：「昔周自后稷至于文王，積德累功，參分天下，猶服事殷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0299-a04-006-1', 'p0299', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '主簿閻象進曰：「昔周自后稷至于文王，積德累功，參分天下有其二，猶服事殷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0300-a04-028-0', 'p0300', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '淩陰謀滋甚，遣將軍楊弘以廢立事告兖州刺史黃華，華、弘連名以白太傅司馬宣王。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0300-a04-046-1', 'p0300', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '後術死，長史楊弘、大將張勳等將其衆欲就策，廬江太守劉勳要擊，悉虜之，收其珍寶以歸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0301-a04-006-0', 'p0301', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '表初到，單馬入宜城，而延中廬人蒯良、蒯越、襄陽人蔡瑁與謀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0302-a04-006-0', 'p0302', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '表初到，單馬入宜城，而延中廬人蒯良、蒯越、襄陽人蔡瑁與謀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0302-a04-006-1', 'p0302', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」表大將蒯越亦勸表，表狐疑，乃遣嵩詣太祖以觀虛實。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0302-a04-032-2', 'p0302', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '曾請備宴會，蒯越、蔡瑁欲因會取備，備覺之，偽如厠，潛遁出。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0303-a04-006-0', 'p0303', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '表初到，單馬入宜城，而延中廬人蒯良、蒯越、襄陽人蔡瑁與謀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0303-a04-006-1', 'p0303', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '初，表及妻愛少子琮，欲以為後，而蔡瑁、張允為之支黨，乃出長子琦為江夏太守，衆遂奉琮為嗣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0303-a04-032-2', 'p0303', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '曾請備宴會，蒯越、蔡瑁欲因會取備，備覺之，偽如厠，潛遁出。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0304-a04-001-0', 'p0304', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '乃論荊州服從之功，侯者十五人，以劉表大將文聘為江夏太守，使統本兵，引用荊州名士韓嵩、鄧義等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0304-a04-006-1', 'p0304', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '從事中郎韓嵩、別駕劉先說表曰：「豪傑並爭，兩雄相持，天下之重在於將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0304-a04-006-2', 'p0304', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '表以為懷貳，大會寮屬數百人，陳兵見嵩，盛怒，持節將斬之，數曰：「韓嵩敢懷貳邪！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0304-a04-006-3', 'p0304', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '表怒不已，其妻蔡氏諫之曰：「韓嵩，楚國之望也；且其言直，誅之無辭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0304-a04-031-4', 'p0304', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '張松、法正，雖有君臣之義不正，然固已委名附質，進不顯陳事勢，若韓嵩、劉先之說劉表，退不告絕奔亡，若陳平、韓信之去項羽，而兩端攜貳，為謀不忠，罪之次也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0305-a03-043-0', 'p0305', 'houhanshu', 'a03-043', '《後漢書·卷四十三》', '後拜為尚書，復上封事曰：「夫忠臣憂世，犯主嚴顏，譏刺貴臣，至以殺身滅家而猶為之者，何邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0305-a03-078-1', 'p0305', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '倫有才學，盡心敦慎，數犯嚴顏，匡弼得失。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0305-a04-019-2', 'p0305', 'sanguozhi', 'a04-019', '《三國志·魏書十九》', '及見之，帝猶嚴顏色，不與語，又不使冠履。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0305-a04-036-3', 'p0305', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '至江州，破璋將巴郡太守嚴顏，生獲顏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0305-a04-036-4', 'p0305', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '羽報效曹公，飛義釋嚴顏，並有國士之風。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0306-a04-032-0', 'p0306', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '璋遣劉璝、冷苞、張任、鄧賢等拒先主於涪，益部耆舊雜記曰：張任，蜀郡人，家世寒門。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0306-a04-032-1', 'p0306', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '十九年夏，雒城破，益部耆舊雜記曰：劉璋遣張任與劉璝率精兵拒捍先主於涪，為先主所破，退與璋子循守雒城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0307-a04-037-0', 'p0307', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '鄭度說璋曰：華陽國志曰：度，廣漢人，為州從事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0308-a03-075-0', 'p0308', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '魯功曹閻圃諫曰：「漢川之民，戶出十萬，四面險固，財富土沃，上匡天子，則為桓文，次方竇融，不失富貴。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0308-a03-075-1', 'p0308', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '閻圃說曰：「今以急往，其功為輕，不如且依巴中，然後委質，功必多也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0308-a03-075-2', 'p0308', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '封魯五子及閻圃等皆為列侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0308-a04-008-3', 'p0308', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '魯功曹巴西閻圃諫魯曰：「漢川之民，戶出十萬，財富土沃，四面險固；上匡天子，則為桓、文，次及竇融，不失富貴。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0308-a04-008-4', 'p0308', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '封魯五子及閻圃等皆為列侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0308-a04-008-5', 'p0308', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '習鑿齒曰：魯欲稱王，而閻圃諫止之，今封圃為列侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0308-a04-008-6', 'p0308', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '今閻圃諫魯勿王，而太祖追封之，將來之人孰不思順！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0308-a04-036-7', 'p0308', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '魯敗，曹公得之，以董賜閻圃，以秋付魯，魯自手殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0309-a03-073-0', 'p0309', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '長史關靖諫曰：「今將軍將士，莫不懷瓦解之心，所以猶能相守者，顧戀其老小，而恃將軍為主故耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0309-a03-073-1', 'p0309', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '關靖見瓚敗，歎恨曰：「前若不止將軍自行，未必不濟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0309-a04-008-2', 'p0309', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '謂關靖曰：「當今四方虎爭，無有能坐吾城下相守經年者明矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0309-a04-008-3', 'p0309', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '長史關靖說瓚曰：「今將軍將士皆已土崩瓦解，其所以能相守持者，顧戀其居處老小，以將軍為主耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0309-a04-008-4', 'p0309', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '英雄記曰：關靖字士起，太原人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0309-a04-008-5', 'p0309', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '漢晉春秋曰：關靖曰：「吾聞君子陷人於危，必同其難，豈可獨生乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0310-a04-006-0', 'p0310', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '遂北排田楷，東攻孔融，曜兵海隅，是時百姓無主，欣戴之矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0310-a04-008-1', 'p0310', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '以嚴綱為兾州，田楷為青州，單經為兖州，置諸郡縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0310-a04-008-2', 'p0310', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '謙引兵擊之，青州刺史田楷亦以兵救謙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0310-a04-032-3', 'p0310', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '為賊所破，往奔中郎將公孫瓚，瓚表為別部司馬，使為青州刺史田楷以拒兾州牧袁紹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0310-a04-032-4', 'p0310', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '袁紹攻公孫瓚，先主與田楷東屯齊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0310-a04-032-5', 'p0310', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '曹公征徐州，徐州牧陶謙遣使告急於田楷，楷與先主俱救之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0310-a04-036-6', 'p0310', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '本屬公孫瓚，瓚遣先主為田楷拒袁紹，雲遂隨從，為先主主騎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0311-a03-073-0', 'p0311', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '初，同郡人笮融，笮音側格反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0311-a04-008-1', 'p0311', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '賊笮融從臨淮見討，迸入郡界，昱將兵拒戰，敗績，見害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0311-a04-046-2', 'p0311', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '時彭城相薛禮、下邳相笮融依繇為盟主，禮據秣陵城，融屯縣南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0311-a04-046-3', 'p0311', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '發恩布令，告諸縣：「其劉繇、笮融等故鄉部曲來降首者，一無所問；樂從軍者，一身行，復除門戶；不樂者，勿彊也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0311-a04-049-4', 'p0311', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '笮融先至，笮音壯力反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0311-a04-049-5', 'p0311', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '許子將謂繇曰：「笮融出軍，不顧命名義者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0311-a04-049-6', 'p0311', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '笮融者，丹楊人，初聚衆數百，往依徐州牧陶謙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0311-a04-050-7', 'p0311', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '會景為劉繇所迫，復北依術，術以為督軍中郎將，與孫賁共討樊能、于麋於橫江，又擊笮融、薛禮於秣陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0311-a04-050-8', 'p0311', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '」琨具啟策，策即行之，衆悉俱濟，遂破英，擊走笮融、劉繇，事業克定。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0311-a04-053-9', 'p0311', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '初，琅邪趙昱為廣陵太守，察紘孝廉，昱後為笮融所殺，紘甚傷憤，而力不能討。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0311-a04-054-10', 'p0311', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '乃渡擊秣陵，破笮融、薛禮，轉下湖孰、江乘，進入曲阿，劉繇奔走，而策之衆已數萬矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0311-a04-056-11', 'p0311', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '策定秣陵、曲阿，收笮融、劉繇餘衆，增範兵二千，騎五十匹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0312-a03-073-0', 'p0312', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '別駕從事趙昱，知名士也，而以忠直見踈，出為廣陵太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0312-a03-073-1', 'p0312', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '廣陵太守趙昱待以賔禮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0312-a04-007-2', 'p0312', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '時選三署郎以補縣長；琅邪趙昱為莒長，東萊劉繇下邑長，東海王朗菑丘長，洪即丘長。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0312-a04-008-3', 'p0312', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '而謙背道任情：廣陵太守琅邪趙昱，徐方名士也，以忠直見疏；謝承漢書曰：昱年十三，母嘗病，經涉三月。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0312-a04-013-4', 'p0312', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '時漢帝在長安，關東兵起，朗為謙治中，與別駕趙昱等說謙曰：「春秋之義，求諸侯莫如勤王。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0312-a04-049-5', 'p0312', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '曹公攻陶謙，徐土搔動，融將男女萬口，馬三千匹，走廣陵，廣陵太守趙昱待以賔禮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0312-a04-052-6', 'p0312', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '少好學，善隷書，從白侯子安受左氏春秋，博覽衆書，與琅邪趙昱、東海王朗俱發名友善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0312-a04-053-7', 'p0312', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '初，琅邪趙昱為廣陵太守，察紘孝廉，昱後為笮融所殺，紘甚傷憤，而力不能討。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0313-a03-009-0', 'p0313', 'houhanshu', 'a03-009', '《後漢書·卷九》', '是歲，孫策死，為許貢客所射傷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0313-a03-112-1', 'p0313', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '興平二年，太守許貢奏分縣為永縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0313-a04-014-2', 'p0313', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '」策臨江未濟，果為許貢客所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0313-a04-038-3', 'p0313', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '禕死，吳郡都尉許貢、會稽太守王朗素與靖有舊，故往保焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0313-a04-046-4', 'p0313', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '軍敗，還鄉里，為許貢所害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0313-a04-046-5', 'p0313', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '許貢來領郡，岱將憲避難於許昭家，求救於陶謙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0313-a04-046-6', 'p0313', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '未發，會為故吳郡太守許貢客所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0313-a04-046-7', 'p0313', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '初，吳郡太守許貢上表於漢帝曰：「孫策驍雄，與項籍相似，宜加貴寵，召還京邑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0313-a04-046-8', 'p0313', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '許貢客，無聞之小人，而能感識恩遇，臨義忘生，卒然奮發，有侔古烈矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0313-a04-056-9', 'p0313', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '治從錢唐欲進到吳，吳郡太守許貢拒之於由拳，治與戰，大破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0314-a04-046-0', 'p0314', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '」策遂詣丹楊依舅，得數百人，而為涇縣大帥祖郎所襲，幾至危殆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0314-a04-046-1', 'p0314', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '行到錢唐，瑀陰圖襲策，遣都尉萬演等密渡江，使持印傳三十餘紐與賊丹楊、宣城、涇、陵陽、始安、黟、歙諸險縣大帥祖郎、焦已及吳郡烏程嚴白虎等，使為內應，伺策軍發，欲攻取諸郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0314-a04-046-2', 'p0314', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '于時彊宗驍帥，祖郎、嚴虎之徒，禽滅已盡，所餘山越，蓋何足慮？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0314-a04-050-3', 'p0314', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '孫策與孫河、呂範依景，合衆共討涇縣山賊祖郎，郎敗走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0314-a04-051-4', 'p0314', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '又從策討陵陽，生得祖郎等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0314-a04-051-5', 'p0314', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '袁術深怨策，乃陰遣間使齎印綬與丹楊宗帥陵陽祖郎等，使激動山越，大合衆，圖共攻策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0314-a04-055-6', 'p0314', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '策甞攻祖郎，大為所圍，普與一騎共蔽扞策，驅馬疾呼，以矛突賊，賊披，策因隨出。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0314-a04-056-7', 'p0314', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '又從攻祖郎於陵陽，太史慈於勇里。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0315-a04-046-0', 'p0315', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '吳人嚴白虎等衆各萬餘人，處處屯聚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0315-a04-046-1', 'p0315', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '有誠於故友，則受嚴白虎也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0315-a04-046-2', 'p0315', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '行到錢唐，瑀陰圖襲策，遣都尉萬演等密渡江，使持印傳三十餘紐與賊丹楊、宣城、涇、陵陽、始安、黟、歙諸險縣大帥祖郎、焦已及吳郡烏程嚴白虎等，使為內應，伺策軍發，欲攻取諸郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0315-a04-046-3', 'p0315', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '策前西征，登陰復遣間使，以印綬與嚴白虎餘黨，圖為後害，以報瑀見破之辱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0315-a04-056-4', 'p0315', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '貢南就山賊嚴白虎，治遂入郡，領太守事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0315-a04-056-5', 'p0315', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '是時下邳陳瑀自號吳郡太守，住海西，與彊族嚴白虎交通。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a03-009-0', 'p0316', 'houhanshu', 'a03-009', '《後漢書·卷九》', '十二年秋八月，曹操大破烏桓於柳城，斬其蹋頓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a03-090-1', 'p0316', 'houhanshu', 'a03-090', '《後漢書·卷九十》', '獻帝初平中，丘力居死，子樓班年少，從子蹋頓有武略，蹋音大蠟反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a03-090-2', 'p0316', 'houhanshu', 'a03-090', '《後漢書·卷九十》', '建安初，兾州牧袁紹與前將軍公孫瓚相持不決，蹋頓遣使詣紹求和親，遂遣兵助擊瓚，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a03-090-3', 'p0316', 'houhanshu', 'a03-090', '《後漢書·卷九十》', '紹矯制賜蹋頓、難樓、蘇僕延、烏延等，皆以單于印綬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a03-090-4', 'p0316', 'houhanshu', 'a03-090', '《後漢書·卷九十》', '後難樓、蘇僕延率其部衆奉樓班為單于，蹋頓為王，然蹋頓猶秉計策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a03-090-5', 'p0316', 'houhanshu', 'a03-090', '《後漢書·卷九十》', '建安十二年，曹操自征烏桓，大破蹋頓於柳城，斬之，首虜二十餘萬人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a03-090-6', 'p0316', 'houhanshu', 'a03-090', '《後漢書·卷九十》', '而靈獻之閒，二虜迭盛，石槐驍猛，盡有單于之地，蹋頓凶桀，公據遼西之土。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a04-001-7', 'p0316', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '遼西單于蹋頓尤彊，為紹所厚，故尚兄弟歸之，數入塞為害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a04-001-8', 'p0316', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '尚、熙與蹋頓、遼西單于樓班、右北平單于能臣抵之等，將數萬騎逆軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a04-001-9', 'p0316', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '公登高，望虜陳不整，乃縱兵擊之，使張遼為先鋒，虜衆大崩，斬蹋頓及名王已下，胡、漢降者二十餘萬口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a04-011-10', 'p0316', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '若嘿回軍，從盧龍口越白檀之險，出空虛之地，路近而便，掩其不備，蹋頓之首可不戰而禽也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a04-011-11', 'p0316', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '斬蹋頓於白狼，遂長驅於柳城，疇有力焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a04-014-12', 'p0316', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '今四州之民，徒以威附，德施未加，舍而南征，尚因烏丸之資，招其死主之臣，胡人一動，民夷俱應，以生蹋頓之心，成覬覦之計，恐青、兾非己之有也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a04-014-13', 'p0316', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '大破之，斬蹋頓及名王已下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a04-014-14', 'p0316', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '後袁尚依烏丸蹋頓，太祖將征之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a04-017-15', 'p0316', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '遂擊，大破之，斬單于蹋頓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a04-017-16', 'p0316', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '從征蹋頓，拜橫野將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a04-030-17', 'p0316', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '其後尚、熈又逃于蹋頓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a04-030-18', 'p0316', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '蹋頓又驍武，邊長老皆比之冒頓，恃其阻遠，敢受亡命，以雄百蠻。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a04-030-19', 'p0316', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '後丘力居死，子樓班年小，從子蹋頓有武略，代立，總攝三王部，衆皆從其教令。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a04-030-20', 'p0316', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '袁紹與公孫瓚連戰不決，蹋頓遣使詣紹求和親，助紹擊瓚，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a04-030-21', 'p0316', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '紹矯制賜蹋頓、峭王、汗魯王印綬，皆以為單于。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a04-030-22', 'p0316', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '版文曰：「使持節大將軍督幽、青、并領兾州牧阮鄉侯紹，承制詔遼東屬國率衆王頒下、烏丸遼西率衆王蹋頓、右北平率衆王汗盧維：乃祖慕義遷善，款塞內附，北捍玁狁，東拒濊貊，世守北陲，為百姓保鄣，雖時侵犯王畧，命將徂征厥罪，率不旋時，悔愆變改，方之外夷，最又聦慧者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a04-030-23', 'p0316', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '後樓班大，峭王率其部衆奉樓班為單于，蹋頓為王。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a04-030-24', 'p0316', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '後袁尚敗奔蹋頓，憑其勢，復圖兾州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a04-030-25', 'p0316', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '建安十一年，太祖自征蹋頓於柳城，潛軍詭道，未至百餘里，虜乃覺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a04-030-26', 'p0316', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '尚與蹋頓將衆逆戰於凡城，兵馬甚盛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a04-030-27', 'p0316', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '太祖登高望虜陣，柳軍未進，觀其小動，乃擊破其衆，臨陣斬蹋頓首，死者被野。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0317-a04-002-0', 'p0317', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '并州刺史梁習討鮮卑軻比能，大破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0317-a04-003-1', 'p0317', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '夏四月，鮮卑附義王軻比能率其種人及丁零大人兒禪詣幽州貢名馬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0317-a04-003-2', 'p0317', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '保塞鮮卑大人步度根與叛鮮卑大人軻比能私通，并州刺史畢軌表，輒出軍以外威比能，內鎮步度根。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0317-a04-009-3', 'p0317', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '時雜虜數為暴，害吏民，軌輒出軍擊鮮卑軻比能，失利。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0317-a04-014-4', 'p0317', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '魏氏春秋曰：烏丸校尉田豫帥西部鮮卑泄歸尼等出塞，討軻比能、智鬱築鞬，破之，還至馬邑故城，比能帥三萬騎圍豫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0317-a04-019-5', 'p0317', 'sanguozhi', 'a04-019', '《三國志·魏書十九》', '時鮮卑大人軻比能將數萬騎觀望彊弱，見彰力戰，所向皆破，乃請服。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0317-a04-026-6', 'p0317', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '鮮卑大人步度根、泄歸泥等與軻比能為隙，將部落三萬餘家詣郡附塞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0317-a04-026-7', 'p0317', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '太和二年，護烏丸校尉田豫出塞，為軻比能所圍於故馬邑城，移招求救。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0317-a04-030-8', 'p0317', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '後鮮卑大人軻比能復制御群狄，盡收匈奴故地，自雲中、五原以東抵遼水，皆為鮮卑庭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0317-a04-030-9', 'p0317', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '建安中，太祖定幽州，步度根與軻比能等因烏丸校尉閻柔上貢獻。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0317-a04-030-10', 'p0317', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '到桑乾，氏等議，以為扶羅韓部威禁寬緩，恐不見濟，更遣人呼軻比能。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0317-a04-030-11', 'p0317', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '後數與軻比能更相攻擊，步度根部衆稍寡弱，將其衆萬餘落保太原、鴈門郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0317-a04-030-12', 'p0317', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '至黃初五年，步度根詣闕貢獻，厚加賞賜，是後一心守邊，不為寇害，而軻比能衆遂彊盛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0317-a04-030-13', 'p0317', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '軻比能本小種鮮卑，以勇健，斷法平端，不貪財物，衆推以為大人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0317-a04-035-14', 'p0317', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '九年，亮復出祁山，以木牛運，漢晉春秋曰：亮圍祁山，招鮮卑軻比能，比能等至故北地石城以應亮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0318-a04-003-0', 'p0318', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '保塞鮮卑大人步度根與叛鮮卑大人軻比能私通，并州刺史畢軌表，輒出軍以外威比能，內鎮步度根。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0318-a04-003-1', 'p0318', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '帝省表曰：「步度根以為比能所誘，有自疑心。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0318-a04-003-2', 'p0318', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '比能遣子將千餘騎迎步度根部落，與尚、弼相遇，戰於樓煩，二將敗沒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0318-a04-003-3', 'p0318', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '步度根部落皆叛出塞，與比能合寇邊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0318-a04-003-4', 'p0318', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '冬十月，步度根部落大人戴胡阿狼泥等詣并州降，朗引軍還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0318-a04-026-5', 'p0318', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '鮮卑大人步度根、泄歸泥等與軻比能為隙，將部落三萬餘家詣郡附塞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0318-a04-030-6', 'p0318', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '魁頭死，弟步度根代立。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0318-a04-030-7', 'p0318', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '步度根旣立，衆稍衰弱，中兄扶羅韓亦別擁衆數萬為大人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0318-a04-030-8', 'p0318', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '建安中，太祖定幽州，步度根與軻比能等因烏丸校尉閻柔上貢獻。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0318-a04-030-9', 'p0318', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '步度根遣使獻馬，帝拜為王。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0318-a04-030-10', 'p0318', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '後數與軻比能更相攻擊，步度根部衆稍寡弱，將其衆萬餘落保太原、鴈門郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0318-a04-030-11', 'p0318', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '步度根乃使人招呼泄歸泥曰：「汝父為比能所殺，不念報仇，反屬怨家。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0318-a04-030-12', 'p0318', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '」由是歸泥將其部落逃歸步度根，比能追之弗及。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0318-a04-030-13', 'p0318', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '至黃初五年，步度根詣闕貢獻，厚加賞賜，是後一心守邊，不為寇害，而軻比能衆遂彊盛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0318-a04-030-14', 'p0318', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '至青龍元年，比能誘步度根深結和親，於是步度根將泄歸泥及部衆悉保比能，寇鈔并州，殺略吏民。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0318-a04-030-15', 'p0318', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '後與東部鮮卑大人素利及步度根三部爭鬪，更相攻擊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0318-a04-030-16', 'p0318', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '步度根數數鈔盜，又殺我弟，而誣我以鈔盜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0318-a04-030-17', 'p0318', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '至青龍元年，比能誘納步度根，使叛并州，與結和親，自勒萬騎迎其累重於陘北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0319-a04-001-0', 'p0319', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '太祖要擊眭固，又擊匈奴於夫羅於內黃，皆大破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0319-a04-001-1', 'p0319', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '魏書曰：於夫羅者，南單于子也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0319-a04-001-2', 'p0319', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '中平中，發匈奴兵，於夫羅率以助漢。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0319-a04-001-3', 'p0319', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '會本國反，殺南單于，於夫羅遂將其衆留中國。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0319-a04-001-4', 'p0319', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '荊州牧劉表斷術糧道，術引軍入陳留，屯封丘，黑山餘賊及於夫羅等佐之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0319-a04-008-5', 'p0319', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '袁紹至河內，楊與紹合，復與匈奴單于於夫羅屯漳水。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0322-a04-011-0', 'p0322', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '魏略純固傳以脂習、王脩、龐淯、文聘、成公英、郭憲、單固七人為一傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0322-a04-011-1', 'p0322', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '其脩、淯、聘三人自各有傳，成公英別見張旣傳，單固見王淩傳，餘習、憲二人列於脩傳後也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0322-a04-015-2', 'p0322', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '旣夜藏精卒三千人為伏，使參軍成公英督千餘騎挑戰，勑使陽退。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0322-a04-015-3', 'p0322', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '魏略曰：成公英，金城人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0323-a03-009-0', 'p0323', 'houhanshu', 'a03-009', '《後漢書·卷九》', '十一月，遼東太守公孫康殺袁尚、袁熙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0323-a03-090-1', 'p0323', 'houhanshu', 'a03-090', '《後漢書·卷九十》', '袁尚與樓班、烏延等皆走遼東，遼東太守公孫康並斬送之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0323-a04-001-2', 'p0323', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '初，遼東太守公孫康恃遠不服。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0323-a04-006-3', 'p0323', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '尚、熈與烏丸逆軍戰，敗走奔遼東，公孫康誘斬之，送其首。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0323-a04-026-4', 'p0323', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '又遼東太守公孫康自稱平州牧，遣使韓忠齎單于印綬往假峭王。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0323-a04-030-5', 'p0323', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '建安中，公孫康出軍擊之，破其國，焚燒邑落。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0323-a04-030-6', 'p0323', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '建安中，公孫康分屯有縣以南荒地為帶方郡，遣公孫模、張敞等收集遺民，興兵伐韓濊，舊民稍出，是後倭韓遂屬帶方。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0324-a04-002-0', 'p0324', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '三月，加遼東太守公孫恭為車騎將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0324-a04-003-1', 'p0324', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '」遼東太守公孫恭兄子淵劫奪恭位，遂以淵領遼東太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0324-a04-011-2', 'p0324', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '文帝即位，徵寧，遂將家屬浮海還郡，公孫恭送之南郊，加贈服物。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0325-a03-085-0', 'p0325', 'houhanshu', 'a03-085', '《後漢書·卷八十五》', '有一女子名曰卑彌呼，年長不嫁，事鬼神道，能以妖惑衆，於是共立為王。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0325-a04-030-1', 'p0325', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '其國本亦以男子為王，住七八十年，倭國亂，相攻伐歷年，乃共立一女子為王，名曰卑彌呼，事鬼道，能惑衆，年已長大，無夫壻，有男弟佐治國。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0325-a04-030-2', 'p0325', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '其年十二月，詔書報倭女王曰：「制詔親魏倭王卑彌呼：帶方太守劉夏遣使送汝大夫難升米、次使都巿牛利奉汝所獻男生口四人，女生口六人、班布二匹二丈，以到。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0325-a04-030-3', 'p0325', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '倭女王卑彌呼與狗奴國男王卑彌弓呼素不和，遣倭載斯、烏越等詣郡說相攻擊狀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0325-a04-030-4', 'p0325', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '卑彌呼以死，大作冢，徑百餘步，徇葬者奴婢百餘人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0325-a04-030-5', 'p0325', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '復立卑彌呼宗女壹與，年十三為王，國中遂定。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0326-a04-030-0', 'p0326', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '景初二年六月，倭女王遣大夫難升米等詣郡，求詣天子朝獻，太守劉夏遣吏將送詣京都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0326-a04-030-1', 'p0326', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '其年十二月，詔書報倭女王曰：「制詔親魏倭王卑彌呼：帶方太守劉夏遣使送汝大夫難升米、次使都巿牛利奉汝所獻男生口四人，女生口六人、班布二匹二丈，以到。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0326-a04-030-2', 'p0326', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '汝來使難升米、牛利涉遠，道路勤勞，今以難升米為率善中郎將，牛利為率善校尉，假銀印青綬，引見勞賜遣還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0326-a04-030-3', 'p0326', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '又特賜汝紺地句文錦三匹、細班華五張、白絹五十匹、金八兩、五尺刀二口、銅鏡百枚、真珠、鈆丹各五十斤，皆裝封付難升米、牛利還到錄受。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0326-a04-030-4', 'p0326', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '其六年，詔賜倭難升米黃幢，付郡假授。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0326-a04-030-5', 'p0326', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '遣塞曹掾史張政等因齎詔書、黃幢，拜假難升米為檄告喻之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0329-a04-030-0', 'p0329', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '伊夷模無子，淫灌奴部，生子名位宮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0329-a04-030-1', 'p0329', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '句麗呼相似為位，似其祖，故名之為位宮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0329-a04-030-2', 'p0329', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '位宮有力勇，便鞌馬，善獵射。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0330-a04-033-0', 'p0330', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '三年春，使越嶲太守張嶷平定越嶲郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0330-a04-043-1', 'p0330', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '軍還，督將軍張嶷等討汶山郡叛羌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0330-a04-043-2', 'p0330', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '又越嶲郡亦乆失土地，忠率將太守張嶷開復舊郡，由此就加安南將軍，進封彭鄉亭侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0330-a04-043-3', 'p0330', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '張嶷字伯岐，巴郡南充國人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0330-a04-043-4', 'p0330', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '益部耆舊傳曰：余觀張嶷儀貌辭令，不能駭人，而其策略足以入筭，果烈足以立威，為臣有忠誠之節，處類有亮直之風，而動必顧典，後主深崇之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0330-a04-043-5', 'p0330', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '王平忠勇而嚴整，張嶷識斷明果，咸以所長，顯名發迹，遇其時也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-009-0', 'p0331', 'houhanshu', 'a03-009', '《後漢書·卷九》', '董卓部曲將李傕、郭汜、樊稠、張濟等反，攻京師。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-009-1', 'p0331', 'houhanshu', 'a03-009', '《後漢書·卷九》', '李傕殺司隷校尉黃琬，甲子，殺司徒王允，皆滅其族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-009-2', 'p0331', 'houhanshu', 'a03-009', '《後漢書·卷九》', '九月，李傕自為車騎將軍，郭汜後將軍，樊稠右將軍，張濟鎮東將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-009-3', 'p0331', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」袁宏紀曰：「是時馬騰以李傕等專亂，以益州刺史劉焉宗室大臣，遣使招引共誅傕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-009-4', 'p0331', 'houhanshu', 'a03-009', '《後漢書·卷九》', '二月乙亥，李傕殺樊稠而與郭汜相攻。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-009-5', 'p0331', 'houhanshu', 'a03-009', '《後漢書·卷九》', '三月丙寅，李傕脅帝幸其營，焚宮室。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-009-6', 'p0331', 'houhanshu', 'a03-009', '《後漢書·卷九》', '丁酉，郭汜攻李傕，矢及御前。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-009-7', 'p0331', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」是日，李傕移帝幸北塢。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-009-8', 'p0331', 'houhanshu', 'a03-009', '《後漢書·卷九》', '五月壬午，李傕自為大司馬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-009-9', 'p0331', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」張濟復反，與李傕、郭汜合。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-009-10', 'p0331', 'houhanshu', 'a03-009', '《後漢書·卷九》', '十一月庚午，李傕、郭汜等追乘輿，戰於東澗，王師敗績，殺光祿勳鄧泉、衞尉士孫瑞、廷尉宣播、大長秋苗祀、獻帝春秋「播」作「璠」也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-009-11', 'p0331', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」楊奉、董承引白波帥胡才、李樂、韓暹及匈奴左賢王去卑，率師奉迎，與李傕等戰，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-009-12', 'p0331', 'houhanshu', 'a03-009', '《後漢書·卷九》', '李傕等復來追戰，王師大敗，殺略宮人，少府田芬、大司農張義等皆戰歿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-009-13', 'p0331', 'houhanshu', 'a03-009', '《後漢書·卷九》', '三年夏四月，遣謁者裴茂率中郎將段煨討李傕，夷三族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-010b-full-14', 'p0331', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '及李傕破長安，遣兵鈔關東，略得姬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-010b-full-15', 'p0331', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '帝尋而東歸，李傕、郭汜等追敗乘輿於曹陽，帝乃潛夜度河走，度所在今陝州陝縣北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-010b-16', 'p0331', 'houhanshu', 'a03-010b', '《《後漢書》卷十下·皇后紀第十下（獻帝伏皇后節錄）》', '帝尋而東歸，李傕、郭汜等追敗乘輿於曹陽，帝乃潛夜度河走，〈度所在今陝州陝縣北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-027-17', 'p0331', 'houhanshu', 'a03-027', '《後漢書·卷二十七》', '李傕殺司徒王允，復代允為司徒，數月病免，拜尚書令。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-027-18', 'p0331', 'houhanshu', 'a03-027', '《後漢書·卷二十七》', '時李傕與郭汜相攻，傕遂虜掠禁省，劫帝幸北塢，外內隔絕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-027-19', 'p0331', 'houhanshu', 'a03-027', '《後漢書·卷二十七》', '李傕從弟應，溫故掾也，諫之數日，乃獲免。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-045-20', 'p0331', 'houhanshu', 'a03-045', '《後漢書·卷四十五》', '吳書曰，忠字嘉謀，與朱儁共敗李傕於曹陽也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-052-21', 'p0331', 'houhanshu', 'a03-052', '《後漢書·卷五十二》', '及李傕入長安，為亂兵所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-054-22', 'p0331', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '及李傕脅帝歸其營，竒與黃門侍郎鍾繇誘傕部曲將宋曅、楊昂令反傕，傕由此孤弱，帝乃得東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-054-23', 'p0331', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '及李傕、郭汜之亂，彪盡節衞主，崎嶇危難之間，幾不免於害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-056-24', 'p0331', 'houhanshu', 'a03-056', '《後漢書·卷五十六》', '李傕、郭汜之亂，長安城潰，百官多避兵衝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-056-25', 'p0331', 'houhanshu', 'a03-056', '《後漢書·卷五十六》', '」遂與馬騰、韓遂及左中郎劉範、諫議大夫馬宇共攻李傕、郭汜，以報其仇。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-061-26', 'p0331', 'houhanshu', 'a03-061', '《後漢書·卷六十一》', '及卓將李傕、郭汜攻破長安，遂收琬下獄死，時年五十二。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-064-27', 'p0331', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '及李傕專政，使太傅馬日磾撫慰天下，以歧為副。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-066-28', 'p0331', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '」卓部曲將李傕、郭汜等先將兵在關東，因不自安，遂合謀為亂，攻圍長安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-066-29', 'p0331', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '是時三輔民庶熾盛，兵穀富實，李傕等欲即殺允，懼二郡為患，乃先徵翼、宏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-066-30', 'p0331', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '宏遣使謂翼曰：「郭汜、李傕以我二人在外，故未危王公。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-070-31', 'p0331', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '會兾州牧同郡韓馥遣騎迎之，彧乃獨將宗族從馥，留者後多為董卓將李傕所殺略焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-071-32', 'p0331', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '尋李傕作亂，嵩亦病卒，贈驃騎將軍印綬，拜家一人為郎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-071-33', 'p0331', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '董卓聞之，使其將李傕、郭汜等數萬人屯河南拒儁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-071-34', 'p0331', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '陶謙以儁名臣，數有戰功，可委以大事，乃與諸豪桀共推儁為太師，因移檄牧伯，同討李傕等，奉迎天子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-071-35', 'p0331', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '」國家旣遭董卓，重以李傕、郭汜之禍，幼主劫執，忠良殘敝，長安隔絕，不知吉凶。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-071-36', 'p0331', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '」會李傕用太尉周忠、尚書賈詡策，徵儁入朝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-071-37', 'p0331', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '未發，會李傕殺樊稠，而郭汜又自疑，與傕相攻，長安中亂，故儁止不出，留拜大司農。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-071-38', 'p0331', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '獻帝詔儁與太尉楊彪等十餘人譬郭汜，令與李傕和。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-072-39', 'p0331', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '卓遣將李傕詣堅求和，堅拒絕不受，進軍大谷，距洛九十里。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-072-40', 'p0331', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '輔分遣其校尉李傕、郭汜、張濟將步騎數萬，英雄記：「傕，北地人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-072-41', 'p0331', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '及李傕之叛，乃召文才、整脩，使東曉喻之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-072-42', 'p0331', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '李傕、郭汜、樊稠等皆為將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-072-43', 'p0331', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '袁宏紀曰「李傕數設酒請汜，或留汜止宿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-072-44', 'p0331', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '汜恐變生，乃弃軍還就李傕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-072-45', 'p0331', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '李傕、郭汜旣悔令天子東，乃來救段煨，因欲劫帝而西，楊定為汜所遮，亡奔荊州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-072-46', 'p0331', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '李傕謂左右曰：「尚可活不？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-072-47', 'p0331', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '三年，使謁者僕射裴茂詔關中諸將段煨等討李傕，夷三族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-073-48', 'p0331', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '時董卓雖誅，而李傕、郭汜作亂關中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-073-49', 'p0331', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '初三輔遭李傕亂，百姓流移依謙者皆殲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-074-50', 'p0331', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '其冬，車駕為李傕等所追於曹陽，沮授說紹曰：「將軍累葉台輔，世濟忠義。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-075-51', 'p0331', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '興平元年，征西將軍馬騰與範謀誅李傕，焉遣叟兵五千助之，漢世謂蜀為叟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-075-52', 'p0331', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '李傕入長安，欲結術為援，乃授以左將軍，假節，封陽翟侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-075-53', 'p0331', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '允旣不赦涼州人，由是卓將李傕等遂相結，還攻長安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-075-54', 'p0331', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '時李傕等購募求布急，楊下諸將皆欲圖之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-089-55', 'p0331', 'houhanshu', 'a03-089', '《後漢書·卷八十九》', '建安元年，獻帝自長安東歸，右賢王去卑與白波賊帥韓暹等侍衞天子，拒擊李傕、郭汜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-102-56', 'p0331', 'houhanshu', 'a03-102', '《二十四史-後漢書-志第十二‧天文下》', '及司徒王允與將軍呂布誅卓，卓部曲將郭汜、李傕旋兵攻長安，公卿百官吏民戰死者且萬人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-103-57', 'p0331', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '袁山松書曰：「李傕等攻破長安城，害允等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-103-58', 'p0331', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '至二年春，李傕、郭汜鬬長安中，傕迫劫天子，移置傕塢，盡燒宮殿、城門、官府、民舍，放兵寇鈔公卿以下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-103-59', 'p0331', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '是時李傕、郭汜專權縱肆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-108-60', 'p0331', 'houhanshu', 'a03-108', '《二十四史-後漢書-志第十八‧五行六》', '」是時李傕、郭汜專政。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-109-61', 'p0331', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '及靈帝遭黃巾，獻帝即位而董卓興亂，大焚宮廟，劫御西遷，京師蕭條，豪桀並爭，郭汜、李傕之屬，殘害又甚，是以興平、建安之際，海內凶荒，天子奔流，白骨盈野，故陝津之難，以箕撮指，安邑之東，后裳不完，遂有寇戎，雄雌未定，割剝庶民，三十餘年。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-001-62', 'p0331', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '卓將李傕、郭汜等殺允攻布，布敗，東出武關。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-006-63', 'p0331', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '初，卓女壻中郎將牛輔典兵別屯陝，分遣校尉李傕、郭汜、張濟略陳留、潁川諸縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-006-64', 'p0331', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '及李傕之叛，允乃呼文才、整脩使東解釋之，不假借以溫顏，謂曰：「關東鼠子欲何為邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-006-65', 'p0331', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '獻帝紀曰：是時新遷都，宮人多亡衣服，帝欲發御府繒以與之，李傕弗欲，曰：「宮中有衣，胡為復作邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-006-66', 'p0331', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '李傕曰「我邸閣儲偫少」，乃悉載置其營。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-006-67', 'p0331', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '多又劫質公卿，所為如是，而君苟欲利郭多，李傕有膽自知之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-006-68', 'p0331', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」酈言：「我累世受恩，身又常在幃幄，君辱臣死，當坐國家，為李傕所殺，則天命也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-006-69', 'p0331', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '李傕入長安，欲結術為援，以術為左將軍，封陽翟侯，假節，遣太傅馬日磾因循行拜授。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-006-70', 'p0331', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '李傕、郭汜入長安，欲連表為援，乃以表為鎮南將軍、荊州牧，封成武侯，假節。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-007-71', 'p0331', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '由是李傕等遂相結還攻長安城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-008-72', 'p0331', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '董卓敗，濟與李傕等擊呂布，為卓報仇。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-010-73', 'p0331', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '」卓遣李傕等出關東，所過虜略，至潁川、陳留而還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-010-74', 'p0331', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '卓敗，輔又死，衆恐懼，校尉李傕、郭汜、張濟等欲解散，間行歸鄉里。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-010-75', 'p0331', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '獻帝紀曰：天子旣東，而李傕來追，王師敗績。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-013-76', 'p0331', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '是時，漢帝在西京，李傕、郭汜等亂長安中，與關東斷絕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-014-77', 'p0331', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '昭為太祖作書與長安諸將李傕、郭汜等，各隨輕重致殷勤。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-017-78', 'p0331', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '布為李傕所敗，從布東奔徐州，領魯相，時年二十八。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-017-79', 'p0331', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '李傕、郭汜之亂長安也，晃說奉，令與天子還洛陽，奉從其計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-023-80', 'p0331', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '建安初，以奉使率導關中諸將討李傕有功，封列侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-028-81', 'p0331', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '卓將李傕、郭汜等為卓報仇，入長安，殺允，盡害其家。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-032-82', 'p0331', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '承謂服曰：「郭多有數百兵，壞李傕數萬人，但足下與吾同不耳！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-046-83', 'p0331', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '李傕、郭汜相攻，劫質天子公卿，儁性剛，即發病而卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-046-84', 'p0331', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '卓憚堅猛壯，乃遣將軍李傕等來求和親，令堅列疏子弟任刺史、郡守者，許表用之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-046-85', 'p0331', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '」艾曰：「堅雖時見計，故自不如李傕、郭汜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-009-0', 'p0332', 'houhanshu', 'a03-009', '《後漢書·卷九》', '董卓部曲將李傕、郭汜、樊稠、張濟等反，攻京師。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-009-1', 'p0332', 'houhanshu', 'a03-009', '《後漢書·卷九》', '九月，李傕自為車騎將軍，郭汜後將軍，樊稠右將軍，張濟鎮東將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-009-2', 'p0332', 'houhanshu', 'a03-009', '《後漢書·卷九》', '三月，韓遂、馬騰與郭汜、樊稠戰於長平觀，遂、騰敗績，左中郎將劉範、前益州刺史种劭戰歿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-009-3', 'p0332', 'houhanshu', 'a03-009', '《後漢書·卷九》', '八月，馮翊羌叛，寇屬縣，郭汜、樊稠擊破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-009-4', 'p0332', 'houhanshu', 'a03-009', '《後漢書·卷九》', '二月乙亥，李傕殺樊稠而與郭汜相攻。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-009-5', 'p0332', 'houhanshu', 'a03-009', '《後漢書·卷九》', '丁酉，郭汜攻李傕，矢及御前。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-009-6', 'p0332', 'houhanshu', 'a03-009', '《後漢書·卷九》', '郭汜自為車騎將軍，楊定為後將軍，楊奉為興義將軍，董承為安集將軍，並侍送乘輿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-009-7', 'p0332', 'houhanshu', 'a03-009', '《後漢書·卷九》', '冬十月戊戌，郭汜使其將伍習夜燒所幸學舍，逼脅乘輿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-009-8', 'p0332', 'houhanshu', 'a03-009', '《後漢書·卷九》', '楊定、楊奉與郭汜戰，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-009-9', 'p0332', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」張濟復反，與李傕、郭汜合。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-009-10', 'p0332', 'houhanshu', 'a03-009', '《後漢書·卷九》', '十一月庚午，李傕、郭汜等追乘輿，戰於東澗，王師敗績，殺光祿勳鄧泉、衞尉士孫瑞、廷尉宣播、大長秋苗祀、獻帝春秋「播」作「璠」也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-010b-full-11', 'p0332', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '帝尋而東歸，李傕、郭汜等追敗乘輿於曹陽，帝乃潛夜度河走，度所在今陝州陝縣北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-010b-12', 'p0332', 'houhanshu', 'a03-010b', '《《後漢書》卷十下·皇后紀第十下（獻帝伏皇后節錄）》', '帝尋而東歸，李傕、郭汜等追敗乘輿於曹陽，帝乃潛夜度河走，〈度所在今陝州陝縣北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-027-13', 'p0332', 'houhanshu', 'a03-027', '《後漢書·卷二十七》', '時李傕與郭汜相攻，傕遂虜掠禁省，劫帝幸北塢，外內隔絕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-027-14', 'p0332', 'houhanshu', 'a03-027', '《後漢書·卷二十七》', '今與郭汜爭睚眥之隙，以成千鈞之讎，睚眥，解見竇融傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-054-15', 'p0332', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '及李傕、郭汜之亂，彪盡節衞主，崎嶇危難之間，幾不免於害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-056-16', 'p0332', 'houhanshu', 'a03-056', '《後漢書·卷五十六》', '李傕、郭汜之亂，長安城潰，百官多避兵衝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-056-17', 'p0332', 'houhanshu', 'a03-056', '《後漢書·卷五十六》', '」遂與馬騰、韓遂及左中郎劉範、諫議大夫馬宇共攻李傕、郭汜，以報其仇。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-061-18', 'p0332', 'houhanshu', 'a03-061', '《後漢書·卷六十一》', '及卓將李傕、郭汜攻破長安，遂收琬下獄死，時年五十二。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-066-19', 'p0332', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '」卓部曲將李傕、郭汜等先將兵在關東，因不自安，遂合謀為亂，攻圍長安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-066-20', 'p0332', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '宏遣使謂翼曰：「郭汜、李傕以我二人在外，故未危王公。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-071-21', 'p0332', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '董卓聞之，使其將李傕、郭汜等數萬人屯河南拒儁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-071-22', 'p0332', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '」國家旣遭董卓，重以李傕、郭汜之禍，幼主劫執，忠良殘敝，長安隔絕，不知吉凶。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-071-23', 'p0332', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '未發，會李傕殺樊稠，而郭汜又自疑，與傕相攻，長安中亂，故儁止不出，留拜大司農。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-071-24', 'p0332', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '獻帝詔儁與太尉楊彪等十餘人譬郭汜，令與李傕和。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-072-25', 'p0332', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '輔分遣其校尉李傕、郭汜、張濟將步騎數萬，英雄記：「傕，北地人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-072-26', 'p0332', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '李傕、郭汜、樊稠等皆為將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-072-27', 'p0332', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '傕使兄子利共郭汜、樊稠與騰等戰於長平觀下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-072-28', 'p0332', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '猶加稠及郭汜開府，與三公合為六府，皆參選舉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-072-29', 'p0332', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '」與郭汜相攻連月，死者以萬數。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-072-30', 'p0332', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '遷郭汜車騎將軍，楊定後將軍，楊奉興義將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-072-31', 'p0332', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '』董承、楊定言曰：『郭汜今且將七百騎來入煨營。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-072-32', 'p0332', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '李傕、郭汜旣悔令天子東，乃來救段煨，因欲劫帝而西，楊定為汜所遮，亡奔荊州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-073-33', 'p0332', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '時董卓雖誅，而李傕、郭汜作亂關中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-087-34', 'p0332', 'houhanshu', 'a03-087', '《後漢書·卷八十七》', '興平元年，馮翊降羌反，寇諸縣，郭汜、樊稠擊破之，斬首數千級。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-089-35', 'p0332', 'houhanshu', 'a03-089', '《後漢書·卷八十九》', '建安元年，獻帝自長安東歸，右賢王去卑與白波賊帥韓暹等侍衞天子，拒擊李傕、郭汜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-102-36', 'p0332', 'houhanshu', 'a03-102', '《二十四史-後漢書-志第十二‧天文下》', '及司徒王允與將軍呂布誅卓，卓部曲將郭汜、李傕旋兵攻長安，公卿百官吏民戰死者且萬人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-103-37', 'p0332', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '至二年春，李傕、郭汜鬬長安中，傕迫劫天子，移置傕塢，盡燒宮殿、城門、官府、民舍，放兵寇鈔公卿以下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-103-38', 'p0332', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '是時李傕、郭汜專權縱肆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-108-39', 'p0332', 'houhanshu', 'a03-108', '《二十四史-後漢書-志第十八‧五行六》', '」是時李傕、郭汜專政。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-109-40', 'p0332', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '及靈帝遭黃巾，獻帝即位而董卓興亂，大焚宮廟，劫御西遷，京師蕭條，豪桀並爭，郭汜、李傕之屬，殘害又甚，是以興平、建安之際，海內凶荒，天子奔流，白骨盈野，故陝津之難，以箕撮指，安邑之東，后裳不完，遂有寇戎，雄雌未定，割剝庶民，三十餘年。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a04-001-41', 'p0332', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '卓將李傕、郭汜等殺允攻布，布敗，東出武關。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a04-006-42', 'p0332', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '初，卓女壻中郎將牛輔典兵別屯陝，分遣校尉李傕、郭汜、張濟略陳留、潁川諸縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a04-006-43', 'p0332', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '傕對帝，或言「明陛下」，或言「明帝」，為帝說郭汜無狀，帝亦隨其意荅應之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a04-006-44', 'p0332', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '郭汜復欲脅天子還都郿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a04-006-45', 'p0332', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '李傕、郭汜入長安，欲連表為援，乃以表為鎮南將軍、荊州牧，封成武侯，假節。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a04-007-46', 'p0332', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '英雄記曰：郭汜在城北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a04-010-47', 'p0332', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '卓敗，輔又死，衆恐懼，校尉李傕、郭汜、張濟等欲解散，間行歸鄉里。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a04-010-48', 'p0332', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '獻帝紀曰：郭汜、樊稠與傕互相違戾，欲鬬者數矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a04-010-49', 'p0332', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '獻帝紀曰：傕時召羌、胡數千人，先以御物繒綵與之，又許以宮人婦女，欲令攻郭汜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a04-013-50', 'p0332', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '是時，漢帝在西京，李傕、郭汜等亂長安中，與關東斷絕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a04-014-51', 'p0332', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '昭為太祖作書與長安諸將李傕、郭汜等，各隨輕重致殷勤。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a04-017-52', 'p0332', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '李傕、郭汜之亂長安也，晃說奉，令與天子還洛陽，奉從其計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a04-028-53', 'p0332', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '卓將李傕、郭汜等為卓報仇，入長安，殺允，盡害其家。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a04-046-54', 'p0332', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '李傕、郭汜相攻，劫質天子公卿，儁性剛，即發病而卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a04-046-55', 'p0332', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '」艾曰：「堅雖時見計，故自不如李傕、郭汜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0333-a03-009-0', 'p0333', 'houhanshu', 'a03-009', '《後漢書·卷九》', '董卓部曲將李傕、郭汜、樊稠、張濟等反，攻京師。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0333-a03-009-1', 'p0333', 'houhanshu', 'a03-009', '《後漢書·卷九》', '九月，李傕自為車騎將軍，郭汜後將軍，樊稠右將軍，張濟鎮東將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0333-a03-009-2', 'p0333', 'houhanshu', 'a03-009', '《後漢書·卷九》', '三月，韓遂、馬騰與郭汜、樊稠戰於長平觀，遂、騰敗績，左中郎將劉範、前益州刺史种劭戰歿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0333-a03-009-3', 'p0333', 'houhanshu', 'a03-009', '《後漢書·卷九》', '八月，馮翊羌叛，寇屬縣，郭汜、樊稠擊破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0333-a03-009-4', 'p0333', 'houhanshu', 'a03-009', '《後漢書·卷九》', '二月乙亥，李傕殺樊稠而與郭汜相攻。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0333-a03-071-5', 'p0333', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '且傕、汜小豎，樊稠庸兒，無他遠略，又埶力相敵，變難必作。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0333-a03-071-6', 'p0333', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '未發，會李傕殺樊稠，而郭汜又自疑，與傕相攻，長安中亂，故儁止不出，留拜大司農。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0333-a03-072-7', 'p0333', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '傕隨道收兵，比至長安，已十餘萬，與卓故部曲樊稠、李蒙等合，袁宏紀曰：「蒙後為傕所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0333-a03-072-8', 'p0333', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '李傕、郭汜、樊稠等皆為將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0333-a03-072-9', 'p0333', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '自拜署傕為揚武將軍，汜為揚烈將軍，樊稠等皆為中郎將」也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0333-a03-072-10', 'p0333', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '傕令樊稠及兄子利數萬人攻圍槐里，夜梯城，城陷，斬稟梟首。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0333-a03-072-11', 'p0333', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '傕使兄子利共郭汜、樊稠與騰等戰於長平觀下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0333-a03-072-12', 'p0333', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '明年春，傕因會刺殺樊稠於坐，獻帝紀曰：「傕見稠果勇而得衆心，疾害之，醉酒，潛使外生騎都尉胡封於坐中拉殺稠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0333-a03-087-13', 'p0333', 'houhanshu', 'a03-087', '《後漢書·卷八十七》', '興平元年，馮翊降羌反，寇諸縣，郭汜、樊稠擊破之，斬首數千級。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0333-a04-006-14', 'p0333', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '與卓故部曲樊稠、李蒙、王方等合圍長安城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0333-a04-006-15', 'p0333', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '九州春秋曰：馬騰、韓遂之敗，樊稠追至陳倉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0333-a04-010-16', 'p0333', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '獻帝紀曰：郭汜、樊稠與傕互相違戾，欲鬬者數矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0334-a03-008-full-0', 'p0334', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '司空袁逢罷，太常張濟為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0334-a03-008-full-1', 'p0334', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '司空張濟罷，大司農張溫為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0334-a03-008-2', 'p0334', 'houhanshu', 'a03-008', '《後漢書·卷八》', '司空袁逢罷，太常張濟為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0334-a03-008-3', 'p0334', 'houhanshu', 'a03-008', '《後漢書·卷八》', '司空張濟罷，大司農張溫為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0334-a03-009-4', 'p0334', 'houhanshu', 'a03-009', '《後漢書·卷九》', '董卓部曲將李傕、郭汜、樊稠、張濟等反，攻京師。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0334-a03-009-5', 'p0334', 'houhanshu', 'a03-009', '《後漢書·卷九》', '九月，李傕自為車騎將軍，郭汜後將軍，樊稠右將軍，張濟鎮東將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0334-a03-009-6', 'p0334', 'houhanshu', 'a03-009', '《後漢書·卷九》', '六月庚午，張濟自陝來和傕、汜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0334-a03-009-7', 'p0334', 'houhanshu', 'a03-009', '《後漢書·卷九》', '張濟為票騎將軍，還屯陝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0334-a03-009-8', 'p0334', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」張濟復反，與李傕、郭汜合。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0334-a03-054-9', 'p0334', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '初，賜與太尉劉寬、司空張濟濟字元江，細陽人也，張酺曾孫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0334-a03-057-10', 'p0334', 'houhanshu', 'a03-057', '《後漢書·卷五十七》', '時太尉許戫、司空張濟承望內官，受取貨賂，其宦者子弟賔客雖貪汙穢濁，皆不敢問，而虛糺邊遠小郡清脩有惠化者二十六人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0334-a03-072-11', 'p0334', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '輔分遣其校尉李傕、郭汜、張濟將步騎數萬，英雄記：「傕，北地人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0334-a03-072-12', 'p0334', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '汜後將軍，稠右將軍，張濟為鎮東將軍，並封列侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0334-a03-072-13', 'p0334', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '張濟自陝來和解二人，仍欲遷帝權幸弘農。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0334-a03-072-14', 'p0334', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '以張濟為驃騎將軍，復還屯陝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0334-a03-072-15', 'p0334', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '而張濟與楊奉、董承不相平，乃反合傕、汜，共追乘輿，大戰於弘農東澗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0334-a03-072-16', 'p0334', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '張濟飢餓，出至南陽，攻穰，戰死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0334-a04-006-17', 'p0334', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '初，卓女壻中郎將牛輔典兵別屯陝，分遣校尉李傕、郭汜、張濟略陳留、潁川諸縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0334-a04-006-18', 'p0334', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '張濟與郭多、楊定有謀，又為冠帶所附。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0334-a04-006-19', 'p0334', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '張濟自陝和解之，天子乃得出，至新豐、霸陵間。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0334-a04-006-20', 'p0334', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '張濟引兵入荊州界，攻穰城，為流矢所中死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0334-a04-010-21', 'p0334', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '卓敗，輔又死，衆恐懼，校尉李傕、郭汜、張濟等欲解散，間行歸鄉里。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0335-a03-072-0', 'p0335', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '卓先遣將徐榮、李蒙四出虜掠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0335-a03-072-1', 'p0335', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '傕隨道收兵，比至長安，已十餘萬，與卓故部曲樊稠、李蒙等合，袁宏紀曰：「蒙後為傕所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0335-a04-006-2', 'p0335', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '與卓故部曲樊稠、李蒙、王方等合圍長安城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0336-a03-006-0', 'p0336', 'houhanshu', 'a03-006', '《後漢書·卷六》', '四年春正月庚辰，中常侍張逵、蘧政、楊定等有罪誅，事見梁商傳也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0336-a03-009-1', 'p0336', 'houhanshu', 'a03-009', '《後漢書·卷九》', '郭汜自為車騎將軍，楊定為後將軍，楊奉為興義將軍，董承為安集將軍，並侍送乘輿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0336-a03-009-2', 'p0336', 'houhanshu', 'a03-009', '《後漢書·卷九》', '楊定、楊奉與郭汜戰，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0336-a03-072-3', 'p0336', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '安西將軍楊定者，故卓部曲將也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0336-a03-072-4', 'p0336', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '遷郭汜車騎將軍，楊定後將軍，楊奉興義將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0336-a03-072-5', 'p0336', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '初，楊定與煨有隙，遂誣煨欲反，乃攻其營，十餘日不下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0336-a03-072-6', 'p0336', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '袁宏紀曰：「煨與楊定有隙，煨迎乘輿，不敢下馬，揖馬上。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0336-a03-072-7', 'p0336', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '』董承、楊定言曰：『郭汜今且將七百騎來入煨營。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0336-a03-072-8', 'p0336', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '李傕、郭汜旣悔令天子東，乃來救段煨，因欲劫帝而西，楊定為汜所遮，亡奔荊州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0336-a03-101-9', 'p0336', 'houhanshu', 'a03-101', '《二十四史-後漢書-志第十一‧天文中》', '其四年正月，祀南郊，夕牲，中常侍張逵、蘧政、楊定、內者令石光、尚方令傅福等與中常侍曹騰、孟賁爭權，白帝言騰、賁與商謀反，矯詔命收騰、賁，賁自解說，順帝寤，解騰、賁縛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0336-a04-006-10', 'p0336', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '張濟與郭多、楊定有謀，又為冠帶所附。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a03-009-0', 'p0337', 'houhanshu', 'a03-009', '《後漢書·卷九》', '郭汜自為車騎將軍，楊定為後將軍，楊奉為興義將軍，董承為安集將軍，並侍送乘輿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a03-009-1', 'p0337', 'houhanshu', 'a03-009', '《後漢書·卷九》', '楊定、楊奉與郭汜戰，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a03-009-2', 'p0337', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」楊奉、董承引白波帥胡才、李樂、韓暹及匈奴左賢王去卑，率師奉迎，與李傕等戰，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a03-009-3', 'p0337', 'houhanshu', 'a03-009', '《後漢書·卷九》', '癸卯，安國將軍張楊為大司馬，韓暹為將軍，楊奉為車騎將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a03-070-4', 'p0337', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '衆多以山東未定，韓暹、楊奉負功恣睢，恣睢，肆怒貌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a03-070-5', 'p0337', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '韓暹、楊奉，安足恤哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a03-072-6', 'p0337', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '傕將楊奉本白波賊帥，乃將兵救傕，於是汜衆乃退。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a03-072-7', 'p0337', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '遷郭汜車騎將軍，楊定後將軍，楊奉興義將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a03-072-8', 'p0337', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '而張濟與楊奉、董承不相平，乃反合傕、汜，共追乘輿，大戰於弘農東澗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a03-072-9', 'p0337', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '董承、李樂擁衞左右，胡才、楊奉、韓暹、去卑為後距。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a03-072-10', 'p0337', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '乃以張楊為大司馬，楊奉為車騎將軍，韓暹為大將軍，領司隷校尉，皆假節鉞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a03-072-11', 'p0337', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '楊奉、韓暹欲要遮車駕，不及，曹操擊之，獻帝春秋曰：「車駕出洛陽，自轘轅而東，楊奉、韓暹引軍追之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a03-075-12', 'p0337', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '袁術怒布殺韓胤，遣其大將張勳、橋蕤等與韓暹、楊奉連埶，步騎數萬，七道攻布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a04-001-13', 'p0337', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '秋七月，楊奉、韓暹以天子還洛陽，獻帝春秋曰：天子初至洛陽，幸城西故中常侍趙忠宅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a04-001-14', 'p0337', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '韓暹、楊奉專用威命，君則致討，克黜其難，遂遷許都，造我京畿，設官兆祀，不失舊物，天地鬼神於是獲乂，此又君之功也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a04-006-15', 'p0337', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '楊奉，白波帥耳，猶知將軍所為非是，將軍雖拜寵之，猶不肯盡力也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a04-006-16', 'p0337', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '傕將楊奉與傕軍吏宋果等謀殺傕，事泄，遂將兵叛傕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a04-007-17', 'p0337', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '使人於山陽界亡失文字，太祖又手書厚加慰勞布，說起迎天子，當平定天下意，并詔書購捕公孫瓚、袁術、韓暹、楊奉等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a04-007-18', 'p0337', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '術怒，與韓暹、楊奉等連勢，遣大將張勳攻布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a04-008-19', 'p0337', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '建安元年，楊奉、董承、韓暹挾天子還舊京，糧乏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a04-010-20', 'p0337', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '太祖議奉迎都許，或以山東未平，韓暹、楊奉新將天子到洛陽，北連張楊，未可卒制。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a04-014-21', 'p0337', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '會天子還洛陽，韓暹、楊奉、董承及楊各違戾不和。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a04-014-22', 'p0337', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '楊奉近在梁耳，聞其兵精，得無為孤累乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a04-017-23', 'p0337', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '為郡吏，從車騎將軍楊奉討賊有功，拜騎都尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a04-032-24', 'p0337', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '楊奉、韓暹寇徐、揚閒，先主邀擊，盡斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a03-009-0', 'p0338', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」楊奉、董承引白波帥胡才、李樂、韓暹及匈奴左賢王去卑，率師奉迎，與李傕等戰，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a03-009-1', 'p0338', 'houhanshu', 'a03-009', '《後漢書·卷九》', '二月，韓暹攻衞將軍董承。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a03-009-2', 'p0338', 'houhanshu', 'a03-009', '《後漢書·卷九》', '癸卯，安國將軍張楊為大司馬，韓暹為將軍，楊奉為車騎將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a03-070-3', 'p0338', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '衆多以山東未定，韓暹、楊奉負功恣睢，恣睢，肆怒貌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a03-070-4', 'p0338', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '韓暹、楊奉，安足恤哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a03-072-5', 'p0338', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '承、奉乃譎傕等與連和，而密遣閒使至河東，招故白波帥李樂、韓暹、胡才及南匈奴右賢王去卑，並率其衆數千騎來，與承、奉共擊傕等，大破之，斬首數千級，乘輿乃得進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a03-072-6', 'p0338', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '董承、李樂擁衞左右，胡才、楊奉、韓暹、去卑為後距。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a03-072-7', 'p0338', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '建安元年春，諸將爭權，韓暹遂攻董承，承奔張楊，楊乃使承先繕修洛宮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a03-072-8', 'p0338', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '乃以張楊為大司馬，楊奉為車騎將軍，韓暹為大將軍，領司隷校尉，皆假節鉞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a03-072-9', 'p0338', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '操乃詣闕貢獻，稟公卿以下，因奏韓暹、張楊之罪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a03-072-10', 'p0338', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '楊奉、韓暹欲要遮車駕，不及，曹操擊之，獻帝春秋曰：「車駕出洛陽，自轘轅而東，楊奉、韓暹引軍追之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a03-075-11', 'p0338', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '袁術怒布殺韓胤，遣其大將張勳、橋蕤等與韓暹、楊奉連埶，步騎數萬，七道攻布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a03-089-12', 'p0338', 'houhanshu', 'a03-089', '《後漢書·卷八十九》', '建安元年，獻帝自長安東歸，右賢王去卑與白波賊帥韓暹等侍衞天子，拒擊李傕、郭汜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a04-001-13', 'p0338', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '秋七月，楊奉、韓暹以天子還洛陽，獻帝春秋曰：天子初至洛陽，幸城西故中常侍趙忠宅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a04-001-14', 'p0338', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '韓暹、楊奉專用威命，君則致討，克黜其難，遂遷許都，造我京畿，設官兆祀，不失舊物，天地鬼神於是獲乂，此又君之功也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a04-006-15', 'p0338', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '奉急招河東故白波帥韓暹、胡才、李樂等合，與傕、汜大戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a04-007-16', 'p0338', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '使人於山陽界亡失文字，太祖又手書厚加慰勞布，說起迎天子，當平定天下意，并詔書購捕公孫瓚、袁術、韓暹、楊奉等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a04-007-17', 'p0338', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '術怒，與韓暹、楊奉等連勢，遣大將張勳攻布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a04-008-18', 'p0338', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '建安元年，楊奉、董承、韓暹挾天子還舊京，糧乏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a04-010-19', 'p0338', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '太祖議奉迎都許，或以山東未平，韓暹、楊奉新將天子到洛陽，北連張楊，未可卒制。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a04-014-20', 'p0338', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '會天子還洛陽，韓暹、楊奉、董承及楊各違戾不和。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a04-014-21', 'p0338', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '奉由是失望，與韓暹等到定陵鈔暴。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a04-017-22', 'p0338', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '及到洛陽，韓暹、董承日爭鬬，晃說奉令歸太祖；奉欲從之，後悔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a04-032-23', 'p0338', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '楊奉、韓暹寇徐、揚閒，先主邀擊，盡斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0339-a03-009-0', 'p0339', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」楊奉、董承引白波帥胡才、李樂、韓暹及匈奴左賢王去卑，率師奉迎，與李傕等戰，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0339-a03-072-1', 'p0339', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '承、奉乃譎傕等與連和，而密遣閒使至河東，招故白波帥李樂、韓暹、胡才及南匈奴右賢王去卑，並率其衆數千騎來，與承、奉共擊傕等，大破之，斬首數千級，乘輿乃得進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0339-a03-072-2', 'p0339', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '董承、李樂擁衞左右，胡才、楊奉、韓暹、去卑為後距。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0339-a03-072-3', 'p0339', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '拜胡才征東將軍，張楊為安國將軍，皆假節、開府。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0339-a03-072-4', 'p0339', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '」胡才、李樂留河東，才為怨家所害，樂自病死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0339-a04-006-5', 'p0339', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '奉急招河東故白波帥韓暹、胡才、李樂等合，與傕、汜大戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0340-a03-009-0', 'p0340', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」楊奉、董承引白波帥胡才、李樂、韓暹及匈奴左賢王去卑，率師奉迎，與李傕等戰，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0340-a03-072-1', 'p0340', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '承、奉乃譎傕等與連和，而密遣閒使至河東，招故白波帥李樂、韓暹、胡才及南匈奴右賢王去卑，並率其衆數千騎來，與承、奉共擊傕等，大破之，斬首數千級，乘輿乃得進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0340-a03-072-2', 'p0340', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '董承、李樂擁衞左右，胡才、楊奉、韓暹、去卑為後距。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0340-a03-072-3', 'p0340', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '李樂懼，欲令車駕御舡過砥柱，出盟津。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0340-a03-072-4', 'p0340', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '』」使李樂先度具舟舡，舉火為應。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0340-a03-072-5', 'p0340', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '」止於人家，然後幸李樂營。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0340-a03-072-6', 'p0340', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '」胡才、李樂留河東，才為怨家所害，樂自病死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0340-a04-006-7', 'p0340', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '奉急招河東故白波帥韓暹、胡才、李樂等合，與傕、汜大戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0340-a04-006-8', 'p0340', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '及當北渡，使李樂具船。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0341-a04-032-0', 'p0341', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '武陵太守金旋、長沙太守韓玄、桂陽太守趙範、零陵太守劉度皆降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0341-a04-036-1', 'p0341', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '及曹公克荊州，假行裨將軍，仍就故任，統屬長沙太守韓玄。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0342-a04-032-0', 'p0342', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '武陵太守金旋、長沙太守韓玄、桂陽太守趙範、零陵太守劉度皆降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0342-a04-032-1', 'p0342', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '三輔決錄注曰：金旋字元機，京兆人，歷位黃門郎、漢陽太守，徵拜議郎，遷中郎將，領武陵太守，為備所攻劫死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0343-a04-032-0', 'p0343', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '武陵太守金旋、長沙太守韓玄、桂陽太守趙範、零陵太守劉度皆降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0343-a04-036-1', 'p0343', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '從平江南，以為偏將軍，領桂陽太守，代趙範。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0344-a03-001-0', 'p0344', 'houhanshu', 'a03-001', '《後漢書·卷一上》', '太中大夫徐惲擅殺臨淮太守劉度，惲坐誅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0344-a03-038-1', 'p0344', 'houhanshu', 'a03-038', '《後漢書·卷三十八》', '又武陵蠻夷悉反，寇掠江陵閒，荊州刺史劉度、南郡太守李肅並奔走荊南，皆沒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0344-a03-038-2', 'p0344', 'houhanshu', 'a03-038', '《後漢書·卷三十八》', '又遣謁者馬睦，督荊州刺史劉度擊之，軍敗，睦、度奔走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0344-a03-038-3', 'p0344', 'houhanshu', 'a03-038', '《後漢書·卷三十八》', '桓帝詔公卿舉任代劉度者，尚書朱穆舉尚，自右校令擢為荊州刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0344-a03-086-4', 'p0344', 'houhanshu', 'a03-086', '《後漢書·卷八十六》', '冬，武陵蠻六千餘人寇江陵，荊州刺史劉度、謁者馬睦、南郡太守李肅皆奔走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0344-a04-032-5', 'p0344', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '武陵太守金旋、長沙太守韓玄、桂陽太守趙範、零陵太守劉度皆降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a03-073-0', 'p0345', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '紹與故虎牙都尉劉勳，首共造兵，勳降服張楊，累有功効，而以小忿枉加酷害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a03-075-1', 'p0345', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '妻子依故吏廬江太守劉勳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a03-112-2', 'p0345', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '尋陽有置馬亭，劉勳士衆散處。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-001-3', 'p0345', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '廬江太守劉勳率衆降，封為列侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-001-4', 'p0345', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '於是中軍師王凌、謝亭侯荀攸、前軍師東武亭侯鍾繇、左軍師涼茂、右軍師毛玠、平虜將軍華鄉侯劉勳、建武將軍清苑亭侯劉若、伏波將軍高安侯夏侯惇、揚武將軍都亭侯王忠、奮威將軍樂鄉侯劉展、建忠將軍昌鄉亭侯鮮于輔、奮武將軍安國亭侯程昱、太中大夫都鄉侯賈詡、軍師祭酒千秋亭侯董昭、都亭侯薛洪、南鄉亭侯董蒙、關內侯王粲、傅巽、祭酒王選、袁奐、王朗、張承、任藩、杜襲、中護軍國明亭侯曹洪、中領軍萬歲亭侯韓浩、行驍騎將軍安平亭侯曹仁、領護軍將軍王圖、長史萬潛、謝奐、袁霸等勸進曰：「自古三代，胙臣以土，受命中興，封秩輔佐，皆所以襃功賞德，為國藩衞也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-002-5', 'p0345', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '甞與平虜將軍劉勳、奮威將軍鄧展等共飲，宿聞展善有手臂，曉五兵，又稱其能空手入白刃。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-004-6', 'p0345', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '使保林李華、劉勳等與懷、信等戲，清商令令狐景呵華、勳曰：『諸女，上左右人，各有官職，何以得爾？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-006-7', 'p0345', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '妻子依術故吏廬江太守劉勳，孫策破勳，復見收視。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-007-8', 'p0345', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '臣松之案：公孫瓚表列紹罪過云：「紹與故虎牙將軍劉勳首共造兵，勳仍有效，而以小忿枉害於勳，紹罪七也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-008-9', 'p0345', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '紹與故虎牙都尉劉勳首共造兵，勳仍有効，又降伏張楊，而以小忿枉害於勳，信用讒慝，殺害有功，紹罪七也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-012-10', 'p0345', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '征虜將軍劉勳，貴寵驕豪，又芝故郡將，賔客子弟在界數犯法。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-014-11', 'p0345', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '曄覩漢室漸微，己為支屬，不欲擁兵，遂委其部曲與廬江太守劉勳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-015-12', 'p0345', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '沛辭去，未到鄴，而軍中豪右曹洪、劉勳等畏沛，各遣家馳騎告子弟，使各自檢勑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-016-13', 'p0345', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '杜氏新書曰：平虜將軍劉勳，為太祖所親，貴震朝廷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-029-14', 'p0345', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '」琅琊劉勳為河內太守，有女年幾二十，左脚膝裏上有瘡，癢而不痛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-046-15', 'p0345', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '」策攻康，拔之，術復用其故吏劉勳為太守，策益失望。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-046-16', 'p0345', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '後術死，長史楊弘、大將張勳等將其衆欲就策，廬江太守劉勳要擊，悉虜之，收其珍寶以歸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-046-17', 'p0345', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '軍嚴當進，會術死，術從弟胤、女壻黃猗等畏懼曹公，不敢守壽春，乃共舁術棺柩，扶其妻子及部曲男女，就劉勳於皖城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-047-18', 'p0345', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '建安四年，從策征廬江太守劉勳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-051-19', 'p0345', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '時策已平吳、會二郡，賁與策征廬江太守劉勳、江夏太守黃祖，軍旋，聞繇病死，過定豫章，上賁領太守，江表傳曰：時丹楊僮芝自署廬陵太守，策留賁弟輔領兵住南昌，策謂賁曰：「兄今據豫章，是扼僮芝咽喉而守其門戶矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-051-20', 'p0345', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '策西襲廬江太守劉勳，輔隨從，身先士卒，有功。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-054-21', 'p0345', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '」復進尋陽，破劉勳，討江夏，還定豫章、廬陵，留鎮巴丘。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-055-22', 'p0345', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '後拜盪寇中郎將，領零陵太守，從討劉勳於尋陽，進攻黃祖於沙羨，還鎮石城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-055-23', 'p0345', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '從征劉勳，破黃祖，還討鄱陽，領樂安長，山越畏服。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-055-24', 'p0345', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '策破劉勳，多得廬江人，料其精銳，乃以武為督，所向無前。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-055-25', 'p0345', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '從策攻皖，又討劉勳於尋陽，伐黃祖於江夏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0346-a03-075-0', 'p0346', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '術大怒，遣其將張勳、橋蕤攻布，大敗而還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0346-a03-075-1', 'p0346', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '術聞大駭，即走度淮，留張勳、橋蕤於蘄陽，水經曰：「蘄水出江夏蘄春縣北山。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0346-a03-075-2', 'p0346', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '袁術怒布殺韓胤，遣其大將張勳、橋蕤等與韓暹、楊奉連埶，步騎數萬，七道攻布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0346-a03-075-3', 'p0346', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '暹、奉大喜，遂共擊勳等於下邳，大破之，生禽橋蕤，餘衆潰走，其所殺傷、墯水死者殆盡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0346-a04-001-4', 'p0346', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '術聞公自來，棄軍走，留其將橋蕤、李豐、梁綱、樂就；公到，擊破蕤等，皆斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0346-a04-001-5', 'p0346', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁術僭逆，肆於淮南，懾憚君靈，用丕顯謀，蘄陽之役，橋蕤授首，稜威南邁，術以隕潰，此又君之功也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0346-a04-006-6', 'p0346', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '以張勳、橋蕤等為大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0346-a04-012-7', 'p0346', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '久之，術與橋蕤俱攻圍蘄陽，蘄陽為太祖固守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0346-a04-017-8', 'p0346', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '從擊呂布於濮陽，張超於雍丘，橋蕤於苦，皆先登有功，封廣昌亭侯。');
